import {patterns} from './pattern-data.mjs';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const videos=[
 ['cloudfront','AT-nHW3_SVI','Introduction to Amazon CloudFront','2019','Saat cache hit, komponen mana yang bisa dilewati?'],
 ['lambda','eOBq__h4OJ4','Introduction to AWS Lambda','2015','Bedakan event pemicu, function code, dan compute yang dikelola AWS.'],
 ['s3','ecv-19sYL3w','Introduction to Amazon S3','2024','Apa bedanya menyimpan object dengan memasang disk ke server?'],
 ['sqs','XrX7rb6M3jw','Introducing Amazon SQS FIFO Queues','2017','Perhatikan apa yang dijaga urutannya. Bandingkan dengan kebutuhan aplikasi.']
];
export function figure(p){return `<figure class="aq-source-figure"><a class="aq-zoom" href="${p.src}" target="_blank" rel="noopener" aria-label="Open full-size diagram: ${e(p.title)}"><img loading="lazy" decoding="async" src="${p.src}" alt="${e(p.alt)}"><span>Full size ↗</span></a><figcaption><strong>${e(p.title)}</strong><p lang="id">${e(p.cue)}</p><a href="${p.source}" target="_blank" rel="noopener">Source: AWS Samples ↗</a></figcaption></figure>`;}
function clip([service,id,title,year,cue]){return `<article class="aq-clip"><div><small>VIDEO · AMAZON WEB SERVICES · ${year}</small><h3>${e(title)}</h3><p lang="id">${e(cue)}</p></div><div class="aq-player"><button type="button" data-play-clip="${id}" class="button">▷ Load video</button> <a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></article>`;}
export function initMedia(){document.addEventListener('click',evt=>{const btn=evt.target.closest('button[data-play-clip]');if(!btn)return;const v=videos.find(x=>x[1]===btn.dataset.playClip);if(!v)return;const frame=document.createElement('iframe');frame.title=v[2];frame.src='https://www.youtube-nocookie.com/embed/'+v[1];frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';btn.replaceWith(frame);});}
export function relatedMedia(ids){const picks=patterns.map(p=>[p,p.services.filter(id=>ids.includes(id)).length]).filter(([,n])=>n).sort((a,b)=>b[1]-a[1]).map(([p])=>p),clips=videos.filter(v=>ids.includes(v[0]));if(!(picks.length+clips.length))return '';return `<section class="aq-context-media"><h3>Look closer · Lihat contohnya</h3>${picks[0]?figure(picks[0]):''}${clips.slice(0,1).map(clip).join('')}${picks.length>1||clips.length>1?`<details><summary>More related media</summary>${picks.slice(1).map(figure).join('')}${clips.slice(1).map(clip).join('')}</details>`:picks.slice(1).map(figure).join('')+clips.slice(1).map(clip).join('')}</section>`;}
export function mediaLibrary(){return `<p class="section-context">VISUAL LEARNING / ENGLISH × BAHASA</p><h1>Visual library.</h1><p class="lede">Pilih contoh yang ingin kamu pahami. Perbesar gambarnya, lalu jawab pertanyaan di bawahnya.</p><nav class="aq-media-links" aria-label="Visual learning tools"><a class="button" href="#visuals">176 illustrated service cards →</a><a class="button" href="#architecture">6 interactive walkthroughs →</a></nav><h2>Architecture in practice</h2><div class="aq-source-grid">${patterns.map(figure).join('')}</div><h2>Watch the mechanism</h2><p>Four AWS introductions for the underlying concepts. Check current documentation for changing limits or pricing.</p><div class="aq-clip-grid">${videos.map(clip).join('')}</div>`;}
